/**
 * Access layer for the copy harvested from engineering.catholic.edu.
 *
 * `site-content.json` is generated by scripts/build-content.py from the crawled
 * main content of every path in the production sitemap. Paths are the
 * production paths, unchanged, so an old link still lands on the same page.
 *
 * The rule that matters: this module renders what the source says. It adds no
 * facts. Where a value is missing it returns undefined and the template leaves
 * the section out, rather than filling it in.
 */
import raw from "@/content/site-content.json";
import newsMeta from "@/content/news-meta.json";
import dims from "@/content/media-dims.json";

export type Run =
  | { t: "x"; x: string }
  | { t: "s"; x: string; b?: true; i?: true }
  | { t: "a"; x?: string | null; href: string; ext?: boolean };

export type Card = {
  kind: "story" | "person" | string;
  image?: string | null;
  image_source?: string;
  title?: string | null;
  href?: string;
  date?: string | null;
  role?: string | null;
  department?: string | null;
};

export type Block =
  | { t: "h2" | "h3" | "h4"; x: string; href?: string }
  | { t: "p"; runs: Run[] }
  | { t: "ul" | "ol"; items: Run[][] }
  | { t: "img"; src: string; alt: string }
  | { t: "table"; rows: string[][] }
  | { t: "cards"; kind: string; cards: Card[] };

export type Crumb = { title: string; href: string };

export type ContentImage = { src: string; alt: string; source: string };

export type Page = {
  path: string;
  title: string;
  lead?: string | null;
  type: string;
  breadcrumb: Crumb[];
  blocks: Block[];
  images: ContentImage[];
  words: number;
  emails: string[];
  phones: string[];
  source: string;
  published?: string | null;
  description?: string;
  role?: string | null;
  department?: string | null;
  photo?: string | null;
  alt_issues?: string[];
  person_name?: string | null;
};

type Store = { generated: string; origin: string; pages: Record<string, Page> };

const store = raw as unknown as Store;
export const contentGenerated = store.generated;
export const contentOrigin = store.origin;

/** Paths a hand-authored page owns; the content route must not shadow them. */
const RESERVED = new Set([
  "/",
  "/programs-admission",
  "/programs-admission/undergraduate-programs",
  "/programs-admission/graduate-programs",
  "/programs-admission/certificate-programs",
  "/programs-admission/undergraduate-programs/minors",
  "/programs-admission/request-information",
  "/connect-contact/news-events",
  "/connect-contact/faculty-directory",
  "/connect-contact/contact-us",
]);

const pages = store.pages;

export function getContentPage(path: string): Page | undefined {
  const key = path.length > 1 ? path.replace(/\/$/, "") : "/";
  if (RESERVED.has(key)) return undefined;
  return pages[key];
}

export function contentPaths(): string[] {
  return Object.keys(pages).filter((p) => !RESERVED.has(p));
}

export function servedPaths(): string[] {
  return [...Object.keys(pages), ...RESERVED];
}

export function hasContent(path: string): boolean {
  const key = path.length > 1 ? path.replace(/\/$/, "") : "/";
  return Boolean(pages[key]) && !RESERVED.has(key);
}

/** True when the redesign serves this path, hand-authored or harvested. */
export function isServed(path: string): boolean {
  const key = path.length > 1 ? path.replace(/\/$/, "") : "/";
  return RESERVED.has(key) || Boolean(pages[key]);
}

export function blocksOfType(page: Page, ...types: Block["t"][]): Block[] {
  return page.blocks.filter((b) => types.includes(b.t));
}

export function headingBlocks(page: Page) {
  return page.blocks.filter((b) => b.t === "h2" || b.t === "h3") as (
    | { t: "h2"; x: string }
    | { t: "h3"; x: string }
  )[];
}

/** The picture the source put at the top of the page, if it put one there. */
export function heroImage(page: Page): ContentImage | undefined {
  if (page.photo) {
    const chosen =
      page.images.find((i) => i.src === page.photo) ??
      (page.blocks.find((b) => b.t === "img" && b.src === page.photo) as
        | { src: string; alt: string }
        | undefined);
    if (chosen) return { src: chosen.src, alt: chosen.alt || page.title, source: "" };
  }
  const first = page.blocks.find((b) => b.t === "img");
  if (first && first.t === "img") {
    return page.images.find((i) => i.src === first.src) ?? { src: first.src, alt: first.alt, source: "" };
  }
  return page.images[0];
}

export function imageDims(src: string): { w: number; h: number } | undefined {
  const d = (dims as Record<string, { w: number; h: number }>)[src];
  return d ? d : undefined;
}

/**
 * Breadcrumb. The source page supplies one when Drupal rendered it; otherwise
 * the trail is built from the URL itself, which is the same information.
 */
const SECTION_TITLES: Record<string, string> = {
  "explore-our-college": "Explore Our College",
  "programs-admission": "Programs & Admission",
  "connect-contact": "Connect & Contact",
  "current-students": "Current Students",
  "faculty-staff": "Faculty & Staff",
  about: "About",
};

export function breadcrumbsFor(page: Page): Crumb[] {
  if (page.breadcrumb.length > 0) return page.breadcrumb;
  const parts = page.path.split("/").filter(Boolean);
  const trail: Crumb[] = [{ title: "Home", href: "/" }];
  let acc = "";
  for (const part of parts) {
    acc += `/${part}`;
    if (parts.length === 1 && page.title) {
      trail.push({ title: page.title, href: acc });
      break;
    }
    const title =
      SECTION_TITLES[part] ??
      (pages[acc]?.title ?? part.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()));
    trail.push({ title, href: acc });
  }
  if (trail[trail.length - 1]?.href !== page.path) {
    trail.push({ title: page.title, href: page.path });
  }
  return trail;
}

/** Section id used by the header to decide which nav group is current. */
export function sectionOf(path: string): string {
  const first = path.split("/").filter(Boolean)[0] ?? "";
  return first;
}

// ---------------------------------------------------------------- news

export type StoryMeta = {
  slug: string;
  title: string;
  href: string;
  date: string | null;
  displayDate: string | null;
  thumbnail: string | null;
  thumbnailAlt: string | null;
  categories: string[];
};

const metaList = (newsMeta as unknown as { stories: StoryMeta[] }).stories ?? [];
const metaBySlug = new Map<string, StoryMeta>(metaList.map((m) => [m.slug, m]));

export const newsCategories: string[] =
  (newsMeta as unknown as { categories: string[] }).categories ?? [];

export function storyMeta(path: string): StoryMeta | undefined {
  const slug = path.split("/").filter(Boolean).pop() ?? "";
  return metaBySlug.get(slug);
}

export type Story = {
  slug: string;
  path: string;
  title: string;
  href: string;
  date: Date | null;
  dateLabel: string | null;
  excerpt: string;
  image: ContentImage | undefined;
  categories: string[];
  page: Page;
};

function toDisplayDate(iso: string | null | undefined): Date | null {
  if (!iso) return null;
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? null : d;
}

function label(d: Date | null): string | null {
  if (!d) return null;
  return d.toLocaleDateString("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
    timeZone: "UTC",
  });
}

export function allStories(): Story[] {
  const out: Story[] = [];
  for (const [path, page] of Object.entries(pages)) {
    if (page.type !== "story") continue;
    const slug = path.split("/").filter(Boolean).pop() ?? path;
    const meta = metaBySlug.get(slug);
    const date =
      toDisplayDate(meta?.date ?? null) ?? toDisplayDate(page.published ?? null);
    const img = heroImage(page);
    out.push({
      slug,
      path,
      href: path,
      title: meta?.title ?? page.title,
      date,
      dateLabel: meta?.displayDate ?? label(date),
      excerpt: page.lead ?? "",
      image: img,
      categories: meta?.categories ?? [],
      page,
    });
  }
  return out.sort((a, b) => (b.date?.getTime() ?? 0) - (a.date?.getTime() ?? 0));
}

export function storyYears(stories: Story[]): number[] {
  const years = new Set<number>();
  for (const s of stories) if (s.date) years.add(s.date.getUTCFullYear());
  return [...years].sort((a, b) => b - a);
}

export function storyNeighbours(story: Story): {
  prev: Story | null;
  next: Story | null;
} {
  const list = allStories();
  const i = list.findIndex((s) => s.slug === story.slug);
  return {
    prev: i > 0 ? list[i - 1] : null,
    next: i >= 0 && i < list.length - 1 ? list[i + 1] : null,
  };
}

export function relatedStories(story: Story, count = 3): Story[] {
  const list = allStories();
  const byCategory = list.filter(
    (s) => s.slug !== story.slug && s.categories.some((c) => story.categories.includes(c)),
  );
  const byYear = list.filter(
    (s) => s.slug !== story.slug && s.date && story.date && s.date.getUTCFullYear() === story.date.getUTCFullYear(),
  );
  const seen = new Set<string>();
  const out: Story[] = [];
  for (const s of [...byCategory, ...byYear]) {
    if (seen.has(s.slug)) continue;
    seen.add(s.slug);
    out.push(s);
    if (out.length >= count) break;
  }
  return out;
}

// ---------------------------------------------------------------- people

export type Person = {
  name: string;
  href: string;
  slug: string;
  role?: string | null;
  department?: string | null;
  image?: string | null;
};

/**
 * Everyone in the faculty directory.
 *
 * The directory listing paginates, so the profile pages under
 * /connect-contact/faculty-directory/ are the complete set. The build script
 * merges each listing card's rank, department and headshot onto its profile.
 */
export function directoryPeople(): Person[] {
  const profiles = Object.values(pages)
    .filter(
      (p) =>
        p.type === "faculty" &&
        p.path.startsWith("/connect-contact/faculty-directory/") &&
        p.path.split("/").filter(Boolean).length === 2,
    )
    .map((p) => ({
      name: p.person_name || p.title,
      href: p.path,
      slug: p.path.split("/").filter(Boolean).pop() ?? "",
      role: p.role ?? null,
      department: p.department ?? null,
      image: p.photo ?? null,
    }))
    .sort((a, b) => a.name.localeCompare(b.name));
  if (profiles.length) return profiles;
  return directoryPeopleFromCards();
}

/** Fallback: cards parsed out of the directory page body. */
function directoryPeopleFromCards(): Person[] {
  const dir = pages["/connect-contact/faculty-directory"];
  if (!dir) return [];
  const out: Person[] = [];
  for (const b of dir.blocks) {
    if (b.t !== "cards" || b.kind !== "person") continue;
    for (const c of b.cards) {
      if (!c.href) continue;
      out.push({
        name: c.title ?? "",
        href: c.href,
        slug: c.href.split("/").filter(Boolean).pop() ?? "",
        role: c.role,
        department: c.department,
        image: c.image,
      });
    }
  }
  return out;
}

export function personBySlug(slug: string): Person | undefined {
  return directoryPeople().find((p) => p.slug === slug);
}

export function departmentsFromDirectory(): string[] {
  const set = new Set<string>();
  for (const p of directoryPeople()) if (p.department) set.add(p.department);
  return [...set].sort();
}

// ---------------------------------------------------------------- programs

export function programPages(level: "undergraduate" | "graduate" | "certificate" | "minor") {
  const typeFor = {
    undergraduate: "program-undergraduate",
    graduate: "program-graduate",
    certificate: "program-certificate",
    minor: "minor",
  } as const;
  return Object.values(pages)
    .filter((p) => p.type === typeFor[level])
    .sort((a, b) => a.title.localeCompare(b.title));
}

/** Splits a program page into its named sections, keyed on the source headings. */
export function sectionsOf(page: Page): { heading: string; blocks: Block[] }[] {
  const out: { heading: string; blocks: Block[] }[] = [];
  let current: { heading: string; blocks: Block[] } = { heading: "", blocks: [] };
  for (const b of page.blocks) {
    if (b.t === "h2") {
      if (current.blocks.length || current.heading) out.push(current);
      current = { heading: b.x, blocks: [] };
    } else {
      current.blocks.push(b);
    }
  }
  if (current.blocks.length || current.heading) out.push(current);
  return out;
}

export function findSection(page: Page, match: RegExp): { heading: string; blocks: Block[] } | undefined {
  return sectionsOf(page).find((s) => match.test(s.heading));
}

// ------------------------------------------------- index pages as card grids

export type Entry = {
  title: string;
  href: string;
  image?: string;
  alt?: string;
  excerpt?: string;
};

/**
 * Index pages on the old site repeat one pattern: a picture, a linked title,
 * a short summary. Read back as a list of entries, an index becomes a card grid
 * built entirely from the college's own copy and photography. Everything that
 * is not part of that pattern is returned as `rest` so nothing is dropped.
 */
export function entryCards(page: Page): { cards: Entry[]; rest: Block[] } {
  const cards: Entry[] = [];
  const rest: Block[] = [];
  let pending: { src: string; alt: string } | null = null;
  const blocks = page.blocks;
  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i];
    if (b.t === "img") {
      if (pending) rest.push({ t: "img", src: pending.src, alt: pending.alt });
      pending = { src: b.src, alt: b.alt };
      continue;
    }
    if ((b.t === "h3" || b.t === "h2") && b.href) {
      const next = blocks[i + 1];
      let excerpt: string | undefined;
      if (next && next.t === "p") {
        excerpt = next.runs
          .filter((r) => r.t !== "a")
          .map((r) => ("x" in r ? r.x : ""))
          .join("")
          .trim();
        i += 1;
      }
      cards.push({
        title: b.x,
        href: b.href,
        image: pending?.src,
        alt: pending?.alt,
        excerpt: excerpt || undefined,
      });
      pending = null;
      continue;
    }
    if (pending) {
      rest.push({ t: "img", src: pending.src, alt: pending.alt });
      pending = null;
    }
    rest.push(b);
  }
  if (pending) rest.push({ t: "img", src: pending.src, alt: pending.alt });
  return { cards, rest };
}
